 return {version:MODEL_VERSION,status:'ready',window,sourceLastDate:ordered.at(-1).date,drawCount:ordered.length,objective:{primary:'sixMainNumbers'},method:'Aprendizaje secuencial: los pesos se actualizan tras cada sorteo evaluado según los aciertos de cada método frente a una combinación aleatoria de control; solo se usan resultados ya observados y los seis números principales.',forecast:{targetDate:nextDrawDate(ordered.at(-1).date),afterDate:ordered.at(-1).date,numbers:next.numbers,numberScores:next.numberScores,selectionReasons:explainSelection(ordered,next,window)},lastEvaluation:{targetDate:last.date,trainedThrough:last.trainingEnd,numbers:last.predicted,actual:last.actual,hits:last.hits,selectionReasons:last.selectionReasons},metrics:{simulations:n,meanHits:round(totalHits/n),atLeastThree:histogram.slice(3).reduce((a,b)=>a+b,0),atLeastFour:histogram.slice(4).reduce((a,b)=>a+b,0),maxHits:Math.max(...rows.map(r=>r.hits)),histogram,randomMeanHits:round(totalRandom/n),randomAtLeastThree:randomHistogram.slice(3).reduce((a,b)=>a+b,0),randomAtLeastFour:randomHistogram.slice(4).reduce((a,b)=>a+b,0),randomHistogram},baseline,experts:names.map((name,i)=>{const expertTotal=rows.reduce((s,r)=>s+r.expertHits[i],0),randomTotal=rows.reduce((s,r)=>s+r.randomHits,0),wins=rows.filter(r=>r.expertHits[i]>r.randomHits).length,ties=rows.filter(r=>r.expertHits[i]===r.randomHits).length,losses=rows.length-wins-ties;return {name,initialWeight:1/names.length,meanHits:round(expertTotal/n),atLeastThree:rows.filter(r=>r.expertHits[i]>=3).length,randomMeanHits:round(randomTotal/n),deltaVsRandom:round((expertTotal-randomTotal)/n),beatRandomRate:round(wins/n),wins,ties,losses,numberWeight:round(weights[i])}}),patterns:patterns(ordered),rows,modelState:{version:MODEL_VERSION,window,trainedThrough:ordered.at(-1).date,numberLogWeights:logs,numberWeights:weights}};
